window.ANTZ_I18N = {"meta":{"lang":"pl","source":false,"reviewed":false,"translator":"machine (Claude)"},"ui":{"brand.title":"Przewodnik wdrożeniowy Antz","brand.label":"Przewodnik wdrożeniowy","brand.home":"Antz Systems, strona główna","meta.description":"Krótki, wizualny przewodnik po platformie Antz dla zespołów opieki nad zwierzętami.","nav.primary":"Nawigacja główna","nav.menu":"Menu","nav.modules":"Moduły","nav.why":"Dlaczego Antz","nav.start":"Pierwsze kroki","nav.faq":"FAQ","nav.search":"Przeszukaj przewodnik","nav.searchTip":"Wyszukiwanie (Ctrl/Cmd + K)","footer.tagline":"Dobre dane = dobre wnioski = zdrowe zwierzęta","footer.explore":"Poznaj","footer.talk":"Kontakt z nami","footer.rights":"© 2026 Antz Systems. Wszelkie prawa zastrzeżone.","lang.label":"Język","lang.note":"Ta strona została przetłumaczona maszynowo i oczekuje na weryfikację przez rodzimego użytkownika języka.","lang.english":"Wyświetl po angielsku","lang.dismiss":"Zamknij","lang.inApp":"W aplikacji: {x}","hero.title":"Jedna platforma dla każdego zwierzęcia pod Państwa opieką","hero.sub":"Dokumentacja, codzienne działania i praca zespołowa we wszystkich lokalizacjach. Każde zadanie w Antz, pokazane na prawdziwych ekranach.","hero.areas":"Obszary pracy: {n}","hero.devices":"Urządzenia mobilne i przeglądarka","search.label":"Wyszukaj moduły i funkcje","search.cue":"Szukaj: {x}","search.clear":"Wyczyść wyszukiwanie","search.short":"Aby przeszukać wszystkie moduły i funkcje, należy wpisać co najmniej dwie litery.","search.top":"Najlepsze wyniki","search.none":"Brak wyników dla „{q}”. Proszę spróbować „zwierzę”, „jajo” lub „raport”.","start.label":"Zacznij tutaj","kit.objective.eyebrow":"Zacznij tutaj","kit.objective.more":"Przeczytaj o celu szkolenia","kit.objective.kicker":"Dlaczego prowadzimy to szkolenie","kit.objective.photo":"Opiekun karmiący małe zwierzę w jego wybiegu","kit.platform.eyebrow":"Platforma","kit.platform.more":"Więcej o Antz","kit.platform.why":"Dlaczego warto korzystać z tej aplikacji","kit.platform.photo":"Dłoń trzymająca telefon z aplikacją Antz Systems","kit.start.eyebrow":"Proces wdrożenia","kit.start.more":"Rozpocznij przewodnik","kit.start.features":"Funkcje","day.title":"Jak wygląda pierwszy dzień z Antz","day.lede":"Cztery kroki prowadzą zespół od pierwszego logowania do codziennej pracy.","day.1":"Logowanie do przestrzeni roboczej","day.2":"Poruszanie się po aplikacji","day.3":"Konfiguracja danych podstawowych","day.4":"Nadanie wszystkim właściwych uprawnień","day.4.desc":"Należy utworzyć role odpowiadające strukturze organizacji i włączać uprawnienia moduł po module, tak aby każda osoba widziała to, czego potrzebuje w swojej pracy.","modules.eyebrow":"Co zawiera przewodnik","modules.title":"Poznaj moduły","modules.lede":"Dotknięcie karty otwiera przewodnik po module ze wszystkimi funkcjami i ekranami.","modules.filter":"Filtruj moduły według obszaru","modules.all":"Wszystkie","modules.count":"Moduły: {n}","modules.features":"Funkcje: {n}","spot.tag":"Wyróżniony proces","spot.link":"Szczegóły: {x}","cta.title":"Problem z zadaniem?","cta.text":"Każdy moduł ma w tym przewodniku opis funkcji i prawdziwe ekrany. Można wrócić do miejsca, w którym się skończyło, lub napisać do nas — chętnie pomożemy.","cta.back":"Powrót do modułów","cta.or":"Pytania? Prosimy pisać na {email}","faq.eyebrow":"FAQ","faq.title":"Pytania, które zespoły zadają najpierw","faq.q1":"Czym jest Antz?","faq.q2":"Czy działa na telefonach i komputerach?","faq.a2":"Tak. Aplikacja mobilna obsługuje pracę w terenie, taką jak notatki, leczenie, przeniesienia i rejestry jaj. Aplikacja webowa obsługuje pracę biurową, taką jak system szpitalny, konfiguracja odchowalni, raporty i zapasy apteki. Zmiany pojawiają się w czasie rzeczywistym na telefonie, tablecie i komputerze.","faq.q3":"Czy można kontrolować, kto co widzi?","faq.a3":"Tak. Dostęp opiera się na rolach. Tworzą Państwo role używane w organizacji, na przykład Zoolog, i włączają uprawnienia moduł po module.","faq.q4":"Mamy więcej niż jedną lokalizację. Czy to zadziała?","faq.a4":"Antz przechowuje dane ze wszystkich lokalizacji i działów w jednym miejscu. Pomieszczenia dla zwierząt są uporządkowane według lokalizacji, sekcji i wybiegu, a przeniesienia między lokalizacjami wymagają zatwierdzenia i kontroli wyjazdu przez ochronę.","faq.q5":"Jak zacząć?","faq.a5":"Najlepiej zacząć od przewodnika „Pierwsze kroki”, a następnie otworzyć moduły, z których korzysta Państwa rola. W razie wątpliwości prosimy pisać na hello@antz.systems.","pager.prev":"Poprzednia","pager.next":"Następna","pager.modules":"Poznaj moduły","pager.pages":"Poprzednia i następna strona","pager.moduleNav":"Poprzedni i następny moduł","mod.tabs":"Obszary modułów i moduły","mod.features":"Funkcje","mod.hintClick":"Kliknięcie funkcji otwiera jej ekran","mod.hintTap":"Dotknięcie funkcji otwiera jej ekran","mod.soon":"Ekrany tego modułu będą dostępne wkrótce","mod.zoom":"Dotknięcie ekranu powiększa obraz","win.prev":"Poprzednia funkcja","win.next":"Następna funkcja","win.close":"Zamknij","win.count":"Funkcja {i} z {n}","win.soon":"Ekran będzie dostępny wkrótce","gal.label":"Ekrany: {x}","gal.close":"Zamknij galerię","gal.screen":"Ekran {i}","gal.hint":"Aby powiększyć, rozsuń palce lub stuknij dwukrotnie · Przesuń, aby przeglądać"},"tracks":{"records":{"label":"Dokumentacja i komunikacja","desc":"Najprostsze i najczęściej używane funkcje: notatki, czat i konfiguracja użytkowników."},"animal":{"label":"Ewidencja i przemieszczanie zwierząt","desc":"Kolekcja, pomieszczenia dla zwierząt i każde przemieszczenie zwierzęcia w obrębie zoo."},"medical":{"label":"Medycyna i leczenie","desc":"Dokumentacja, recepty, leczenie i szpitalny system informacyjny."},"mortality":{"label":"Śmiertelność i cykl życia","desc":"Śmiertelność, sekcja zwłok i zarządzanie cyklem życia jaj."},"operations":{"label":"Operacje i nadzór","desc":"Ogłoszenia, helpdesk, ochrona, raportowanie i zgodność z przepisami."}},"modules":{"objective-of-this-kit":{"title":"Cel tego przewodnika","intro":"Wdrożenie ma cztery zadania: zapewnić każdemu członkowi zespołu pewność w codziennych czynnościach, upowszechnić korzystanie z platformy we wszystkich rolach, wskazać luki, które pozwolą nam się doskonalić, oraz ujednolicić sposób prowadzenia dokumentacji we wszystkich lokalizacjach.","features":[{"title":"Rozwój umiejętności","desc":"Poszerzanie wiedzy personelu i praktycznych umiejętności potrzebnych do sprawnego prowadzenia zoo, opieki nad zwierzętami i pewnego korzystania z platformy Antz.","alt":""},{"title":"Wdrożenie systemu","desc":"Zapoznanie użytkowników z każdym modułem aplikacji i zbudowanie pewności w wykonywaniu podstawowych czynności, takich jak rejestrowanie, przeglądanie i zatwierdzanie, bez nadzoru.","alt":""},{"title":"Ciągłe doskonalenie","desc":"Wskazywanie luk, wyjaśnianie wątpliwości i nauka oparta na informacjach zwrotnych, aby z czasem udoskonalać procesy i działanie modułów.","alt":""},{"title":"Standaryzacja","desc":"Spójne procedury we wszystkich zespołach i lokalizacjach oraz jednakowe działanie modułów Wnioski, Śmiertelność, Jaja i Dieta, dzięki czemu każdy wpis wygląda tak samo.","alt":""}]},"what-is-antz-systems":{"title":"Czym jest Antz Systems?","intro":"Antz to kompleksowa platforma do prowadzenia dokumentacji zwierząt, codziennych działań i współpracy zespołu. Gromadzi dane ze wszystkich lokalizacji i działów w jednym miejscu, dzięki czemu każde działanie jest udokumentowane, przejrzyste i możliwe do prześledzenia.","features":[{"title":"Lepsza dokumentacja, lepsza opieka","desc":"Każdy szczegół dokładny, dostępny, opatrzony znacznikiem czasu i przypisany do właściwego zwierzęcia.","alt":""},{"title":"Prosta praca zespołowa","desc":"Bez luk między lekarzami weterynarii, opiekunami i kierownikami — wszyscy pracują na tym samym wpisie.","alt":""},{"title":"Bezpieczeństwo w założeniu","desc":"Dostęp oparty na rolach chroni dane wrażliwe i dopasowuje uprawnienia do struktury organizacyjnej.","alt":""},{"title":"Decyzje na wyciągnięcie ręki","desc":"Szybsze raportowanie i wnioski gotowe na potrzeby kontroli zgodności, bez arkuszy kalkulacyjnych.","alt":""},{"title":"Praca bez papieru","desc":"Mniej błędów przy przepisywaniu i oszczędność czasu na każdej zmianie.","alt":""},{"title":"Aktualizacje w czasie rzeczywistym","desc":"Dostęp do najnowszych informacji zawsze i wszędzie — na telefonie, tablecie i komputerze.","alt":""}],"shots":{"assets/shots/app-welcome-c.jpg":"Ekran powitalny aplikacji Antz Systems: Dobre dane + dobre wnioski = zdrowe zwierzęta."}},"getting-started":{"title":"Pierwsze kroki","intro":"Przewodnik „Pierwsze kroki” przedstawia cel aplikacji i prowadzi nowych użytkowników przez najważniejsze etapy: konfigurację profilu, poznanie kluczowych funkcji i sprawne poruszanie się po platformie.","features":[{"title":"Dostęp i przestrzenie robocze","desc":"Bezpieczne logowanie i dostęp do przypisanego środowiska pracy.","alt":"Ekran główny Antz Systems: pasek wyszukiwania, oczekujące podania leków (Pending Administration), statystyki bieżącego miesiąca z urodzeniami i zgonami (Natality/Mortality) oraz karta ogłoszenia"},{"title":"Nawigacja i interfejs","desc":"Kanał na ekranie głównym z aktualnościami, skróty do szybkiej nawigacji i dolny panel z podstawowymi narzędziami.","alt":""},{"title":"Oczekujące sekcje zwłok / podania leków / przydziały","desc":"Zwierzęta oczekujące na sekcję zwłok, dokumentację administracyjną oraz dalszy przydział lub utylizację przed ostatecznym zamknięciem dokumentacji.","alt":""},{"title":"Konfiguracja podstawowa i moduły","desc":"Konfiguracja danych podstawowych i poznanie modułów, takich jak dokumentacja medyczna, pomieszczenia dla zwierząt, jaja, dieta i zarządzanie zwierzętami.","alt":""},{"title":"Personalizacja","desc":"Zarządzanie notatkami, aktualizacja profilu i ustawienia języka.","alt":""},{"title":"Uprawnienia","desc":"Poziomy dostępu wymagane do bezpiecznej pracy.","alt":""}]},"notes-module":{"title":"Moduł Notatki","intro":"Moduł Notatki gromadzi w jednym miejscu codzienne aktualizacje, obserwacje i zdarzenia powiązane ze zwierzętami, wybiegami i działaniami. Zapewnia uporządkowane wpisy ze znacznikiem czasu, sprawną koordynację zespołu i szybkie wyszukiwanie za pomocą filtrów i tagów, wspierając spójną opiekę, wczesne wykrywanie problemów i zgodność z przepisami.","summary":"Gromadzi codzienne aktualizacje, obserwacje i zdarzenia powiązane ze zwierzętami, wybiegami i działaniami","features":[{"title":"Dodawanie i przeglądanie notatek","desc":"Tworzenie nowych notatek i dostęp do notatek własnych oraz innych upoważnionych użytkowników.","alt":"Formularz nowej notatki: typ notatki, treść, powiadamiani członkowie, obiekt, załączniki, priorytet"},{"title":"Edycja, odsłuchiwanie i usuwanie","desc":"Modyfikowanie, odsłuchiwanie w formie audio lub usuwanie notatek zgodnie z przypisanymi uprawnieniami.","alt":"Szczegóły notatki: Medical, Sick, tygrys AID 425990, z przyciskami edycji i zakładki"},{"title":"Priorytet","desc":"Ustawienie poziomu pilności, aby właściwe osoby zobaczyły notatkę jako pierwsze.","alt":"Szczegóły notatki z flagą priorytetu w prawym górnym rogu"},{"title":"Typ notatki i powiązania","desc":"Kategoryzowanie, powiązanie ze zwierzętami, wybiegami lub sekcjami oraz dołączanie dokumentów.","alt":"Szczegóły notatki z kartą powiązanego zwierzęcia, tygrys AID 425990"},{"title":"Widoczność","desc":"Notatki pojawiają się automatycznie na stronach odpowiedniego zwierzęcia, lokalizacji lub sekcji.","alt":"Karta Notatki na stronie lokalizacji: notatka o higienie widoczna w Central Reserve Kingdom"},{"title":"Powiadomienia i współpraca","desc":"Powiadamianie oznaczonych członków zespołu; polubienia i komentarze utrzymują rozmowę przy temacie.","alt":"Notatka z polubieniem, oznaczonym członkiem zespołu Dr. Cloomy Fernandes i 1 komentarzem"},{"title":"Filtry i wyszukiwanie","desc":"Filtrowanie według słów kluczowych, tagów, autora lub powiązanego obiektu.","alt":"Lista notatek z kartami „Moje notatki” / „Wszystkie notatki” (My Notes / All Notes) i filtrami"}]},"user-management":{"title":"Zarządzanie użytkownikami","intro":"Moduł Użytkownicy umożliwia bezpieczne, scentralizowane zarządzanie kontami, rolami i uprawnieniami. Usprawnia wdrażanie nowych użytkowników, zapewnia bezpieczeństwo danych i dopasowuje prawa dostępu do ról w organizacji, prowadząc szczegółowe dzienniki aktywności na potrzeby rozliczalności.","summary":"Umożliwia bezpieczne, scentralizowane zarządzanie kontami, rolami i uprawnieniami","features":[{"title":"Tworzenie profili i zarządzanie nimi","desc":"Zarządzanie imieniem i nazwiskiem, danymi kontaktowymi, numerem pracownika, datą urodzenia i grupą krwi.","alt":"Formularz podstawowych danych nowego użytkownika: imię i nazwisko, nazwa użytkownika, e-mail, hasło, telefon komórkowy, numer pracownika"},{"title":"Role i uprawnienia","desc":"Przypisywanie ról i zarządzanie prawami dostępu na poziomie modułów.","alt":"Edycja uprawnień: rola Lekarz weterynarii z polami wyboru dostępu do poszczególnych modułów"},{"title":"Kontrola dostępu","desc":"Ograniczanie według lokalizacji/sekcji, aktywacja kont, automatyczne wylogowanie.","alt":"Profil użytkownika z menu Dezaktywuj, Resetuj hasło, Resetuj kod dostępu"},{"title":"Logowanie i odzyskiwanie dostępu","desc":"Bezpieczne logowanie z odzyskiwaniem dostępu za pomocą kodu jednorazowego (OTP) przez SMS lub WhatsApp.","alt":"Ekran resetowania hasła / „Nie pamiętasz hasła?” z polem nazwy użytkownika lub adresu e-mail"},{"title":"Śledzenie aktywności","desc":"Podgląd ostatniego logowania, danych urządzeń i dezaktywacja urządzeń.","alt":"Karta Dziennik w profilu użytkownika: dziennik aktywności z czasem ostatniej aktywności"},{"title":"Informacje dodatkowe","desc":"Rejestrowanie wykształcenia i historii zatrudnienia oraz przesyłanie dokumentów tożsamości.","alt":"Karta Dokumenty tożsamości w profilu użytkownika: karta Aadhaar z załącznikiem"}]},"collection":{"title":"Kolekcja","intro":"Moduł Kolekcja służy do zarządzania wszystkimi aspektami kolekcji zwierząt instytucji i ich dokumentowania. Jest centralnym miejscem rejestrowania gatunków, śledzenia poszczególnych osobników i prowadzenia dokładnej historii taksonomicznej.","summary":"Zarządzanie kolekcją zwierząt instytucji i jej dokumentowanie: rejestr gatunków, śledzenie osobników i dokładna historia taksonomiczna","features":[{"title":"Przegląd gatunku","desc":"Taksonomia, liczebność według płci, liczba pozyskań i urodzeń, z wyszukiwaniem.","alt":"Szczegóły gatunku tygrys z liczebnością, lokalizacjami, sekcjami i wybiegami"},{"title":"Zarządzanie gatunkiem","desc":"Liczebność, odmiany barwne, dane medyczne, dieta, śmiertelność i status sekcji zwłok.","alt":"Szczegóły gatunku tygrys z liczebnością, lokalizacjami, sekcjami i wybiegami"},{"title":"Dodawanie oceny zbiorczej","desc":"Grupowe wprowadzanie danych z nawigacją sekwencyjną i filtrami.","alt":"Lista ocen gatunku z kondycją ciała każdego zwierzęcia"}]},"housing":{"title":"Pomieszczenia dla zwierząt","intro":"Moduł Pomieszczenia dla zwierząt porządkuje siedliska zwierząt we wszystkich lokalizacjach, sekcjach i wybiegach, dzięki czemu miejsce każdego zwierzęcia jest znane, a każda zmiana rejestrowana. Dostęp na każdym poziomie zależy od uprawnień.","summary":"Porządkuje siedliska zwierząt we wszystkich lokalizacjach, sekcjach i wybiegach, dzięki czemu miejsce każdego zwierzęcia jest znane, a każda zmiana rejestrowana","features":[{"title":"Administrowanie lokalizacjami","desc":"Dodawanie i edycja lokalizacji z uprawnieniami opartymi na rolach, zapewniającymi bezpieczny i uporządkowany dostęp.","alt":"Szczegóły lokalizacji: Wildlife Zoological Park z liczbą gatunków, zwierząt i sekcji oraz listą wybiegów"},{"title":"Administrowanie sekcjami","desc":"Dodawanie i edycja sekcji w zoo z kontrolą opartą na uprawnieniach, zapewniającą bezpieczne administrowanie.","alt":"Szczegóły sekcji: Animal Kingdom z liczbą gatunków, zwierząt i wybiegów oraz listą wybiegów"},{"title":"Administrowanie wybiegami","desc":"Dodawanie i edycja wybiegów oraz monitorowanie każdego z nich w celu sprawnego nadzoru nad zwierzętami i danymi.","alt":"Lista wybiegów: Gentle Giants, Herbivores, The Tiger Trail z liczbą zwierząt"}]},"animal-management":{"title":"Zarządzanie zwierzętami","intro":"Moduł Zwierzęta gromadzi w jednym miejscu dokumentację wszystkich zwierząt — aktywnych, przeniesionych, zaginionych lub usuniętych — wraz z profilami, procesami przyjęcia do kolekcji i przejrzystym układem kart.","summary":"Gromadzi dokumentację wszystkich zwierząt w jednym miejscu","features":[{"title":"Wyszukiwanie zwierząt","desc":"Dodawanie nowych zwierząt za pomocą prowadzonych procesów powiązanych z pomieszczeniami, dietą i dokumentacją medyczną.","alt":"Lista zwierząt z licznikami: wszystkie zwierzęta 2828, przeniesione 11, usunięte 27, zaginione/zbiegłe 8"},{"title":"Ostatnio dodane","desc":"Zwierzęta niedawno dodane do systemu, na górze listy.","alt":"Lista ostatnio dodanych: lori, słoń afrykański, tygrys, krokodyl różańcowy, kazuar hełmiasty"},{"title":"Wszystkie zwierzęta","desc":"Kompletna baza danych z możliwością wyszukiwania, filtrowania i eksportu.","alt":"Lista wszystkich zwierząt: królik europejski, kazuar hełmiasty, hipopotam nilowy, tygrys, słoń indyjski"},{"title":"Przeniesione","desc":"Zwierzęta przeniesione między lokalizacjami lub wybiegami, z pełną historią pochodzenia.","alt":"Lista przeniesionych zwierząt: tygrys, lew, lori, baribal, lew"},{"title":"Usunięte","desc":"Dokumentacja usuniętych zwierząt, zachowana na potrzeby audytu i możliwości przywrócenia.","alt":"Lista usuniętych zwierząt"},{"title":"Zaginione / zbiegłe","desc":"Zwierzęta oznaczone jako zaginione lub zbiegłe, powiązane ze zgłoszeniem zdarzenia.","alt":"Lista zaginionych/zbiegłych zwierząt: baribal, kazuar hełmiasty, krokodyl różańcowy, hipopotam nilowy, tygrys"}]},"tags-hub":{"title":"Centrum tagów","intro":"Moduł Centrum tagów pomaga porządkować i kategoryzować różne obiekty (lokalizacje, sekcje, wybiegi, zwierzęta) na platformie ANTZ za pomocą konfigurowalnych etykiet opartych na ich bieżącym statusie, przeznaczeniu lub dowolnej własnej klasyfikacji.","summary":"Pomaga porządkować i kategoryzować obiekty (lokalizacje, sekcje, wybiegi, zwierzęta) na platformie ANTZ za pomocą konfigurowalnych etykiet opartych na statusie, przeznaczeniu lub własnej klasyfikacji","features":[{"title":"Typy tagów — publiczne, prywatne, systemowe","desc":"Porządkowanie i kategoryzowanie obiektów za pomocą tagów publicznych, prywatnych i zdefiniowanych przez system.","alt":"Moje centrum tagów: wyszukiwanie, liczba tagów łącznie/systemowych/publicznych/prywatnych oraz etykiety tagów publicznych i prywatnych"},{"title":"Wyszukiwanie i filtry","desc":"Szybkie wyszukiwanie tagów za pomocą wyszukiwarki i filtrów.","alt":"Moje centrum tagów: wyszukiwanie, liczba tagów łącznie/systemowych/publicznych/prywatnych oraz etykiety tagów publicznych i prywatnych"},{"title":"Tworzenie tagów","desc":"Tworzenie nowych tagów publicznych lub prywatnych zgodnie z potrzebami.","alt":"Tworzenie nowego tagu: nazwa tagu, kategoria tagu, role do powiadomienia, notatki i przycisk „Utwórz tag” (Create Tag)"},{"title":"Edycja i usuwanie tagów","desc":"Zmiana nazwy, koloru lub widoczności tagów prywatnych albo trwałe usuwanie niepotrzebnych tagów.","alt":"Panel szczegółów tagu: kategoria, typ, autor, notatki, oznaczone obiekty oraz akcje edycji i usuwania"},{"title":"Przypisywanie tagów publicznych i prywatnych","desc":"Przypisywanie tagów do lokalizacji, sekcji, wybiegów lub zwierząt w celu łatwego porządkowania.","alt":"Panel dodawania tagu publicznego do lokalizacji: wyszukanie i wybór etykiety tagu, przyciski Anuluj i Dodaj tag"},{"title":"Usuwanie przypisanych tagów","desc":"Usuwanie tagów z lokalizacji, sekcji, wybiegów lub zwierząt w dowolnym momencie.","alt":"Potwierdzenie usunięcia tagu: Czy na pewno usunąć te tagi z tej lokalizacji? Anuluj lub Usuń"},{"title":"Widoczność","desc":"Decydowanie, czy tagi prywatne pozostają osobiste, czy są widoczne dla wszystkich użytkowników.","alt":"Szczegóły tagu prywatnego: typ tagu prywatny (widoczny dla wszystkich) z przełącznikiem udostępnienia tagu wszystkim"},{"title":"Oznaczone obiekty","desc":"Podgląd wszystkich lokalizacji, sekcji, wybiegów, gatunków i zwierząt powiązanych z wybranym tagiem.","alt":"Oznaczone obiekty dla tagu Enclosure Maintenance: karty Zwierzęta / Sekcje / Lokalizacja, Lokalizacja (1) pokazuje lokalizację Bangalore"}]},"animal-transfer":{"title":"Przeniesienia zwierząt","intro":"Rejestruje wszystkie przemieszczenia zwierząt wewnątrz i poza organizacją oraz nimi zarządza, śledząc wnioski, zatwierdzenia i przydziały w celu bezpiecznej i dobrze udokumentowanej relokacji.","summary":"Rejestruje wszystkie przemieszczenia zwierząt wewnątrz i poza organizacją oraz nimi zarządza","features":[{"title":"Rodzaje przeniesień","desc":"Przeniesienia wewnętrzne, między lokalizacjami i zewnętrzne.","alt":"Okno wyboru rodzaju przeniesienia"},{"title":"Zatwierdzanie","desc":"Autoryzacja przez wyznaczone osoby odpowiedzialne w lokalizacji.","alt":"Przeniesienie między lokalizacjami oczekujące na zatwierdzenie"},{"title":"Anulowanie / odrzucenie","desc":"Anulowanie lub odrzucanie wniosków i ponowne ich składanie w razie potrzeby.","alt":"Opcja anulowania przeniesienia"},{"title":"Kontrola wjazdu / wyjazdu przez ochronę","desc":"Kontrolowane odprawy wjazdowe i wyjazdowe przy przeniesieniach między lokalizacjami i zewnętrznych.","alt":"Zgoda ochrony i odprawa wyjazdowa przeniesienia"},{"title":"Przydział","desc":"Po przybyciu przydzielenie zwierzęcia do wybiegu i powiadomienie personelu.","alt":"Zatwierdzone przeniesienie, przydział wybiegów"},{"title":"Dziennik przeniesień","desc":"Pełna historia statusów ze znacznikami czasu i użytkownikami.","alt":"Oś czasu statusu przeniesienia, przeniesienie zakończone"}]},"approvals":{"title":"Zatwierdzenia","intro":"Służy do zarządzania wnioskami o przeniesienie zwierząt i ich śledzenia, zapewniając wgląd we wnioski oczekujące, zatwierdzone i odrzucone. Usprawnia proces weryfikacji, zapewnia właściwą autoryzację i prowadzi przejrzysty rejestr decyzji o przeniesieniach na potrzeby rozliczalności i zgodności z przepisami.","summary":"Zarządzanie wnioskami o przeniesienie zwierząt i ich śledzenie, z wglądem we wnioski oczekujące, zatwierdzone i odrzucone","features":[{"title":"Śledzenie statusu","desc":"Oczekuje na zatwierdzenie, Zatwierdzone, Odrzucone, Zezwolenie na wyjazd/wjazd, Przydzielone.","alt":"Lista zatwierdzeń przeniesień z oznaczeniami statusu"},{"title":"Weryfikacja wniosku","desc":"Podgląd pełnych szczegółów przed zatwierdzeniem.","alt":"Szczegóły wniosku o przeniesienie do weryfikacji"},{"title":"Zatwierdzanie / odrzucanie","desc":"Autoryzacja lub odmowa z odpowiednim uzasadnieniem.","alt":"Szczegóły wniosku o przeniesienie z przyciskami „Zatwierdź” (Approve) i „Odrzuć” (Reject)"},{"title":"Resetowanie zatwierdzenia","desc":"Ponowne otwarcie lub aktualizacja wcześniej zatwierdzonego wniosku.","alt":"Zatwierdzone przeniesienie z opcją „Resetuj zatwierdzenie” (Reset Approval)"},{"title":"Anulowanie przeniesienia","desc":"Anulowanie przed zatwierdzeniem lub po nim, z zapisem przyczyny.","alt":"Szczegóły wniosku z opcją „Anuluj przeniesienie” (Cancel Transfer)"}]},"missing-escaped-animal":{"title":"Zaginione / zbiegłe zwierzę","intro":"Umożliwia szybkie zgłaszanie, śledzenie i wyjaśnianie przypadków zaginięcia lub ucieczki zwierząt, z wpisami ze znacznikiem czasu powiązanymi z ich profilami, co zapewnia rozliczalność i skoordynowane działania ochrony, lekarzy weterynarii i kierownictwa.","summary":"Umożliwia szybkie zgłaszanie, śledzenie i wyjaśnianie przypadków zaginięcia lub ucieczki zwierząt","features":[{"title":"Zgłaszanie zdarzeń i załączniki","desc":"Rejestrowanie szczegółów i podjętych działań oraz przesyłanie zdjęć lub nagrań wideo.","alt":"Formularz zgłoszenia zbiegłego/zaginionego zwierzęcia"},{"title":"Edycja zgłoszenia","desc":"Aktualizowanie lub modyfikowanie zgłoszenia w miarę rozwoju sytuacji.","alt":"Oś czasu zdarzenia, zwierzę zaginione"},{"title":"Zgłaszanie odnalezienia","desc":"Rejestrowanie szczegółów odnalezienia i oznaczanie korekt.","alt":"Formularz zgłoszenia odnalezienia zwierzęcia"},{"title":"Rejestr zdarzeń i identyfikowalność","desc":"Zapis każdego działania w kolejności na osi czasu zwierzęcia.","alt":"Menu opcji z błędnym zgłoszeniem zaginięcia"},{"title":"Widoczność","desc":"Oznaczenie zaginięcia w profilu; szybkie aktualizacje za pomocą kodu QR.","alt":"Profil zwierzęcia z oznaczeniem zaginięcia i kodem QR"}]},"medical-records":{"title":"Dokumentacja medyczna","intro":"Moduł Medyczny pomaga rejestrować, śledzić i zarządzać informacjami o zdrowiu zwierząt, w tym diagnozami, receptami i leczeniem. Wspiera terminową opiekę, uporządkowaną historię medyczną i koordynację między zespołami weterynaryjnymi na rzecz lepszego dobrostanu zwierząt.","summary":"Pomaga rejestrować, śledzić i zarządzać informacjami o zdrowiu zwierząt","features":[{"title":"Tworzenie wpisów","desc":"Różne sposoby dodawania wpisów: pojedynczych, zbiorczych, grupowych, zaplanowanych (szczepienie, odrobaczanie, suplementacja) lub bezpośrednich (podanie leku, recepta, szczepienie, odrobaczanie, suplementacja), z rejestracją dokładnej daty i godziny oraz zleceniami badań laboratoryjnych.","alt":"Menu tworzenia wpisu: pojedynczy, grupowy, zbiorczy wpis medyczny, zbiorcze zlecenie laboratoryjne, bezpośrednie podanie, recepta, szczepienie, odrobaczanie, suplementy"},{"title":"Przegląd wpisu","desc":"Krótkie podsumowanie z danymi lekarza i profilem zwierzęcia dla łatwego wglądu.","alt":"Przegląd wpisu medycznego MED-09501: lekarz, profil zwierzęcia, rodzaj przypadku i objawy"},{"title":"Zakładka, edycja, usuwanie, pobieranie","desc":"Modyfikowanie lub usuwanie wpisów; pobrane raporty są wysyłane e-mailem na zarejestrowany adres.","alt":"Wpis medyczny MED-08805 z ikonami zakładki, edycji i dodatkowych opcji"},{"title":"Oś czasu dziennika medycznego","desc":"Chronologiczny rejestr wszystkich dodań i edycji z pełną identyfikowalnością.","alt":"Dziennik medyczny: chronologiczny rejestr działań na wpisach medycznych ze znacznikami czasu"},{"title":"Ponowne przypisywanie wpisów","desc":"Lekarze z uprawnieniami do edycji mogą przypisać sobie wpisy utworzone pierwotnie przez innego lekarza weterynarii.","alt":"Potwierdzenie ponownego przypisania: Czy przypisać ten wpis medyczny do siebie? Tak / Nie"}]},"symptoms-clinical-assessment-prescription":{"title":"Objawy, ocena kliniczna i recepty","intro":"Funkcja Objawy, ocena kliniczna i recepty zapewnia wgląd w zarejestrowane objawy, diagnozy i przepisane leczenie, pomagając monitorować trendy zdrowotne i wspierając świadome decyzje kliniczne.","summary":"Wgląd w zarejestrowane objawy, diagnozy i przepisane leczenie, pomagający monitorować trendy zdrowotne i wspierający świadome decyzje kliniczne","features":[{"title":"Trendy objawów","desc":"Analiza najczęściej rejestrowanych objawów u różnych gatunków i śledzenie ich występowania w czasie.","alt":"Analiza objawów: 7 gatunków, 7 objawów, lista rankingowa z nieprawidłowymi odchodami, nieprawidłową postawą i nieprawidłowym linieniem na czele"},{"title":"Wnioski z ocen klinicznych","desc":"Monitorowanie ocen klinicznych przeprowadzanych u zwierząt i wskazywanie najczęściej rejestrowanych diagnoz lub schorzeń.","alt":"Analiza ocen klinicznych: 20 gatunków, 35 ocen, na czele choroby wątroby, próchnica zębów i problemy żołądkowo-jelitowe"},{"title":"Analiza recept","desc":"Podgląd najczęściej przepisywanych leków i schematów leczenia u różnych gatunków i w różnych przypadkach.","alt":"Analiza recept: 7 gatunków, 7 recept, na czele Aculife, Fluvac Innovator, Dolo 650"},{"title":"Filtry i wyszukiwanie","desc":"Zawężanie danych według zakresu dat, lokalizacji, gatunku i innych kryteriów.","alt":"Filtr zakresu dat: dzisiaj, wczoraj, ostatnie 7 dni, bieżący miesiąc, ostatnie 3 miesiące, ostatnie 6 miesięcy, wszystkie dane"}]},"administer-medicine":{"title":"Podawanie leków","intro":"Moduł Podawanie uzupełnia dokumentację medyczną, przekładając recepty na konkretne procesy leczenia i umożliwiając udzielanie opieki w czasie rzeczywistym pojedynczym zwierzętom lub grupom, w terenie lub w szpitalu.","summary":"Uzupełnia dokumentację medyczną, przekładając recepty na konkretne procesy leczenia","features":[{"title":"Szybki wpis","desc":"Utworzenie wpisu bezpośredniego podania na wybraną datę bez sporządzania pełnego wpisu medycznego.","alt":"Ekran podawania: pasek dat, karty wpisów zwierząt / grup, kafelki statusów Podane / Pominięte / Wstrzymane / Oczekujące, z wyróżnionym przyciskiem plusa szybkiego wpisu"},{"title":"Wyszukiwanie i filtry","desc":"Szybkie wyszukiwanie wpisów i zawężanie listy według daty, obiektu, gatunku i substancji kontrolowanej.","alt":"Ekran podawania z wyróżnionymi polami wyszukiwania, filtrów, wyboru miesiąca i listą rozwijaną wszystkich wpisów"},{"title":"Śledzenie statusu","desc":"Podgląd leczenia według daty na czterech kartach: Oczekujące, Podane, Pominięte, Wstrzymane.","alt":"Ekran podawania z wyróżnionymi kartami statusów Podane, Pominięte, Wstrzymane, Oczekujące"},{"title":"Działania zbiorcze","desc":"Zaznaczenie wielu wpisów, aby jednocześnie podać lub pominąć leki.","alt":"Ekran podawania z wyróżnionymi opcjami „Zaznacz wszystko” i „Podaj” (Administer) po zaznaczeniu wpisów"},{"title":"Szczegóły recepty","desc":"Pełne informacje — dawkowanie, numer serii, powiązane zwierzę — w chwili podania.","alt":"Ekran recepty z wyróżnionymi godzinami, częstotliwością, czasem trwania i drogą podania"},{"title":"Wpis pojedynczej dawki","desc":"Rejestrowanie pojedynczych dawek z godziną, numerem serii i notatkami.","alt":"Ekran podawania z wyróżnioną kartą grupy pojedynczej dawki i jej polem wyboru"},{"title":"Podgląd na ekranie głównym","desc":"Liczba oczekujących zabiegów widoczna bezpośrednio na ekranie głównym, co przyspiesza działanie.","alt":"Ekran główny aplikacji: kluczowe wskaźniki i karta oczekujących podań leków z 1028 oczekującymi procesami"}],"shots":{"assets/shots/p20-bulk.png":"Działania zbiorcze przy podawaniu: „Zaznacz wszystko”, zaznaczony wpis zwierzęcia oraz przyciski Pominięte / Podaj","assets/shots/p20-prescription.png":"Szczegóły recepty: ID przypadku, godziny, częstotliwość, czas trwania, droga podania, powiązane zwierzę i harmonogram dawek"}},"vaccination":{"title":"Szczepienia","intro":"Moduł Szczepienia obsługuje pełny cykl szczepień zwierząt — od planowania i bezpośredniego podania po śledzenie szczepień nadchodzących, oczekujących, pominiętych i wykonanych. Zapewnia terminowe zabiegi, dokładną rejestrację dawek i pełną identyfikowalność na potrzeby profilaktyki chorób i zgodności klinicznej.","summary":"Obsługuje pełny cykl szczepień zwierząt — od planowania i bezpośredniego podania po śledzenie szczepień nadchodzących, oczekujących, pominiętych i wykonanych","features":[{"title":"Widoki według statusu","desc":"Szczepienia podzielone na Nadchodzące, Oczekujące, Pominięte i Wykonane dla łatwego monitorowania.","alt":"Menu szczepień: Nadchodzące, Oczekujące, Wykonane, Pominięte, Wstrzymane szczepionki, Bezpośrednie podanie, Zaplanuj szczepienie"},{"title":"Zarządzanie szczepieniami","desc":"Planowanie szczepienia lub bezpośrednie zarejestrowanie podanej szczepionki z określonymi datami i szczegółami leku.","alt":"Planowanie szczepienia z wybranymi zwierzętami, receptą i notatkami klinicznymi"},{"title":"Rejestracja podania","desc":"Zapis dawkowania, numeru serii, drogi podania, notatek i opcjonalnej wizyty kontrolnej.","alt":"Szczegóły wykonanego szczepienia z ID przypadku i numerem serii"},{"title":"Oczekujące i nadchodzące","desc":"Wyświetlanie wszystkich zaplanowanych szczepień według daty i lokalizacji, aby żaden zabieg nie został pominięty.","alt":"Oczekujące szczepienia pogrupowane według gatunku"},{"title":"Pominięcie i wstrzymanie","desc":"Przełożenie lub wstrzymanie szczepień z obowiązkowym podaniem przyczyny i daty kontroli.","alt":"Szczegóły oczekującego szczepienia z akcjami Podaj i Pominięte"},{"title":"Dostęp z poziomu zwierzęcia","desc":"Wpisy szczepień można przeglądać w kontekście zwierzęcia, pomieszczeń dla zwierząt lub dokumentacji medycznej.","alt":"Karta Medyczne w profilu zwierzęcia ze szczepieniami oczekującymi, nadchodzącymi i wykonanymi"}]},"deworming":{"title":"Odrobaczanie","intro":"Moduł Odrobaczanie wspiera systematyczne rejestrowanie i monitorowanie zabiegów przeciwpasożytniczych, zapewniając terminowe podanie, właściwą dokumentację i przejrzyste śledzenie każdego odrobaczania u każdego zwierzęcia.","summary":"Wspiera systematyczne rejestrowanie i monitorowanie zabiegów przeciwpasożytniczych","features":[{"title":"Widoki według statusu","desc":"Odrobaczanie podzielone na Nadchodzące, Oczekujące, Pominięte i Wykonane dla łatwego monitorowania.","alt":"Menu odrobaczania: Nadchodzące, Oczekujące, Wykonane, Pominięte, Wstrzymane odrobaczanie, Bezpośrednie podanie, Zaplanuj odrobaczanie"},{"title":"Zarządzanie odrobaczaniem","desc":"Planowanie kuracji lub bezpośrednie zarejestrowanie podanego leku z określonymi datami i szczegółami.","alt":"Bezpośrednie odrobaczanie z wybranym zwierzęciem, receptą i notatkami klinicznymi"},{"title":"Rejestracja podania","desc":"Zapis dawkowania, numeru serii, drogi podania, notatek i opcjonalnej wizyty kontrolnej.","alt":"Dodawanie leku: rodzaj dawki, wielkość dawki, droga podania, kontrola i numer serii"},{"title":"Oczekujące i nadchodzące","desc":"Podgląd wszystkich zaplanowanych odrobaczań według daty i lokalizacji, aby żaden zabieg nie został pominięty.","alt":"Oczekujące odrobaczania pogrupowane według gatunku"},{"title":"Pominięcie i wstrzymanie","desc":"Przełożenie lub wstrzymanie z obowiązkowym podaniem przyczyny i daty kontroli.","alt":"Pominięcie odrobaczania: przełożenie lub wstrzymanie z przyczyną i pytaniem o działania niepożądane"},{"title":"Dostęp z poziomu zwierzęcia","desc":"Wgląd w kontekście zwierzęcia, pomieszczeń dla zwierząt lub dokumentacji medycznej.","alt":"Karta Medyczne w profilu zwierzęcia z odrobaczaniem oczekującym, nadchodzącym i wykonanym"}]},"supplements":{"title":"Suplementy","intro":"Moduł Suplementy wspiera systematyczne rejestrowanie i monitorowanie programów suplementacji żywieniowej, zapewniając terminowe podanie, właściwą dokumentację i przejrzyste śledzenie każdego suplementu podanego każdemu zwierzęciu.","summary":"Wspiera systematyczne rejestrowanie i monitorowanie programów suplementacji żywieniowej","features":[{"title":"Widoki według statusu","desc":"Suplementy podzielone na Nadchodzące, Oczekujące, Pominięte i Wykonane.","alt":"Menu suplementów: Nadchodzące, Oczekujące, Wykonane, Pominięte, Wstrzymane suplementy, Bezpośrednie podanie, Zaplanuj suplementy"},{"title":"Zarządzanie suplementami","desc":"Planowanie lub bezpośrednie zarejestrowanie podanych suplementów z określonymi datami i szczegółami.","alt":"Bezpośrednie podanie suplementów z wybranym zwierzęciem, receptą i notatkami klinicznymi"},{"title":"Rejestracja podania","desc":"Zapis dawkowania, numeru serii, drogi podania, notatek i opcjonalnej wizyty kontrolnej.","alt":"Dodawanie suplementów: rodzaj dawki, wielkość dawki, droga podania, kontrola i numer serii"},{"title":"Oczekujące i nadchodzące","desc":"Wszystkie zaplanowane suplementy według daty i lokalizacji, aby żadne podanie nie zostało pominięte.","alt":"Oczekujące suplementy pogrupowane według gatunku"},{"title":"Pominięcie i wstrzymanie","desc":"Przełożenie lub wstrzymanie z obowiązkowym podaniem przyczyny i daty kontroli.","alt":"Pominięcie suplementów: przełożenie lub wstrzymanie z przyczyną i datą kontroli"},{"title":"Dostęp z poziomu zwierzęcia","desc":"Wpisy dostępne w kontekście zwierzęcia, pomieszczeń dla zwierząt lub dokumentacji medycznej.","alt":"Karta Medyczne w profilu zwierzęcia z suplementami oczekującymi, nadchodzącymi i wykonanymi"}]},"hospital-information-management-system-app":{"title":"Szpitalny system informacyjny (App)","intro":"W aplikacji personel zgłasza przeniesienia zwierząt do szpitala i bezpiecznie przemieszcza pacjentów, podając ID medyczne, rodzaj wizyty, cel i załączniki, z kontrolą wjazdu i wyjazdu przez ochronę w lokalizacji i w szpitalu.","summary":"Personel zgłasza przeniesienia zwierząt do szpitala i bezpiecznie przemieszcza pacjentów","features":[{"title":"Wnioski o przeniesienie","desc":"Zgłaszanie przeniesienia zwierzęcia z wybiegu do szpitala z ID medycznym, rodzajem wizyty, celem i załącznikami.","alt":"Formularz hospitalizacji zwierzęcia: wybrane zwierzę, ID medyczne (utwórz nowe), pola szpitala i rodzaju wizyty, przycisk Wyślij"},{"title":"Status przeniesienia","desc":"Śledzenie każdego przeniesienia na kolejnych etapach: Oczekujące, W transporcie, Przyjęte.","alt":"Przeniesienie HT29-00038: trasa, inicjator, wybrane zwierzę, status „Przeniesienie zakończone” i przycisk odprawy wyjazdowej przez ochronę"},{"title":"Kontrola wjazdu / wyjazdu przez ochronę","desc":"Kontrolowane przemieszczanie pacjentów z odprawą wjazdową i wyjazdową przez ochronę w lokalizacji i w szpitalu.","alt":"Przeniesienie HT29-00038: trasa, inicjator, wybrane zwierzę, status „Przeniesienie zakończone” i przycisk odprawy wyjazdowej przez ochronę"},{"title":"Podgląd wypisów","desc":"Dostęp do kart wypisowych i historii hospitalizacji bezpośrednio w aplikacji.","alt":"Formularz hospitalizacji zwierzęcia: wybrane zwierzę, ID medyczne (utwórz nowe), pola szpitala i rodzaju wizyty, przycisk Wyślij"}]},"hospital-information-management-system-web":{"title":"Szpitalny system informacyjny (Web)","intro":"W konsoli webowej zespoły kliniczne przyjmują i kwalifikują (triaż) nowych pacjentów, monitorują pacjentów hospitalizowanych i ambulatoryjnych, rejestrują leczenie i wypisują zwierzęta, z pełną identyfikowalnością medyczną i raportami do pobrania.","summary":"Zespoły kliniczne przyjmują i kwalifikują pacjentów, monitorują pacjentów hospitalizowanych i ambulatoryjnych, rejestrują leczenie i wypisują zwierzęta","features":[{"title":"Przyjęcie i triaż","desc":"Przyjmowanie lub odrzucanie przypadków z przydziałem lekarza, sali i stanowiska zgodnie z potrzebami leczenia.","alt":"Formularz przyjęcia pacjenta: wybrane zwierzę, cel wizyty, rodzaj leczenia ambulatoryjne / szpitalne, stan zdrowia, przyciski Odrzuć i Przyjmij"},{"title":"Monitorowanie pacjentów hospitalizowanych i ambulatoryjnych","desc":"Konfiguracja i rejestracja zaplanowanych parametrów życiowych i obserwacji z edytowalnymi osiami czasu.","alt":"Lista przyjmowanych pacjentów: karty Oczekujące i Odrzucone ze zwierzętami i celem wizyty"},{"title":"Dokumentacja kliniczna i leczenia","desc":"Objawy, notatki kliniczne, recepty, znieczulenie, zabiegi chirurgiczne i inne formy leczenia w jednym miejscu.","alt":"Karta pacjenta hospitalizowanego MED29-17409: dane przyjęcia i karty Objawy / Ocena kliniczna / Recepta"},{"title":"Wypis","desc":"Wypisanie zwierzęcia z powrotem na wybieg lub rejestracja zgonu ze zleceniem sekcji zwłok i załącznikami.","alt":"Karta Wypis: przyczyna przyjęcia, rodzaj wypisu Zgon / Przeniesienie na wybieg, przycisk „Wypisz zwierzę” (Discharge Animal)"},{"title":"Raporty do pobrania","desc":"Dostęp do kart wypisowych, bieżących danych hospitalizacji i historii wcześniejszych wizyt.","alt":"Lista wypisanych pacjentów z czasem pobytu, rodzajem wizyty, głównym lekarzem weterynarii i opcją pobrania"}]},"mortality":{"title":"Śmiertelność","intro":"Moduł Śmiertelność pozwala szybko i dokładnie rejestrować zgony zwierząt, zarządzać danymi sekcji zwłok i przechowywać dowody w jednym miejscu. Zwiększa przejrzystość, przyspiesza podejmowanie decyzji, zapewnia zgodność z przepisami i wspiera lepsze monitorowanie dobrostanu zwierząt.","summary":"Pozwala szybko i dokładnie rejestrować zgony zwierząt, zarządzać danymi sekcji zwłok i przechowywać dowody w jednym miejscu","features":[{"title":"Panel śmiertelności","desc":"Łączna liczba zgonów, gatunków, których dotyczą, i przyczyn.","alt":"Panel śmiertelności: 2 zwierzęta, 2 gatunki, 2 przyczyny"},{"title":"Listy w wielu widokach","desc":"Wpisy według zwierzęcia, gatunku lub przyczyny, powiązane z profilami.","alt":"Wpisy zgonów według zwierzęcia"},{"title":"Zaawansowane wyszukiwanie i filtry","desc":"Wyszukiwanie według gatunku, przyczyny, miejsca, daty lub słowa kluczowego.","alt":"Wyszukiwanie i filtry śmiertelności"},{"title":"Dokumentacja padłych zwierząt","desc":"Pełne dane o zgonie: przyczyna, ID, wybieg, lokalizacja, płeć.","alt":"Szczegóły wpisu padłego zwierzęcia"},{"title":"Edycja wpisów","desc":"Edycja zgłoszeń zgonu po ich wprowadzeniu, aby zachować ich dokładność.","alt":"Szczegóły zgłoszenia zgonu z opcją edycji"},{"title":"Unieważnianie wpisów","desc":"Unieważnianie błędnych wpisów w celu przywrócenia statusu aktywnego.","alt":"Zgłoszenie zgonu z opcją „Unieważnij zgon” (Revoke Mortality)"},{"title":"Przekazanie zwłok","desc":"Podgląd i śledzenie przemieszczania zwłok między lokalizacjami.","alt":"Lista przekazań zwłok (Carcass Transfers): oczekujące, w transporcie, zakończone"}],"shots":{"assets/shots/p27-mortality-4.jpg":"Karta wpisu zgonu — edycja i unieważnienie"}},"necropsy":{"title":"Sekcja zwłok","intro":"Moduł Sekcja zwłok dokumentuje badania pośmiertne ze szczegółowymi obserwacjami, wynikami dla poszczególnych narządów i wnioskami medycznymi. Wspiera dokładną analizę przyczyny zgonu, ujednolica raportowanie, zapewnia terminowe postępowanie ze zwłokami i spełnia standardy prawne, audytowe i weterynaryjne.","summary":"Dokumentuje badania pośmiertne ze szczegółowymi obserwacjami, wynikami dla poszczególnych narządów i wnioskami medycznymi","features":[{"title":"Wyszukiwanie i filtry","desc":"Wyszukiwanie według zwierzęcia/gatunku; filtrowanie według lokalizacji, daty, priorytetu.","alt":"Lista sekcji zwłok: Przychodzące, Oczekujące, Wersje robocze, Zakończone, z kartami zleceń"},{"title":"Śledzenie statusu","desc":"Monitorowanie etapów: Przychodzące, Oczekujące, Wersja robocza i Zakończone.","alt":"Lista sekcji zwłok z kartami statusów Przychodzące, Oczekujące, Wersje robocze, Zakończone"},{"title":"Karta zwierzęcia i dane zlecenia","desc":"AID, gatunek, miejsce, przyczyna, zlecający, priorytet.","alt":"Lista sekcji zwłok według zwierząt ze szczegółami karty zlecenia"},{"title":"Przekazanie zwłok","desc":"Podgląd wniosków o przekazanie: Oczekuje na przyjęcie, Odebrane.","alt":"Lista przekazań zwłok (Carcass Transfers): Oczekuje na przyjęcie, Odebrane"},{"title":"Szczegółowy widok zlecenia","desc":"Podgląd pełnego zlecenia sekcji zwłok z danymi zwierzęcia i zgonu (przyczyna, stan zwłok, notatki), aktualizacja wpisów, zapis wersji roboczej lub przesłanie po ukończeniu.","alt":"Szczegóły zlecenia sekcji zwłok: zgłoszenie zgonu, przyczyna, stan zwłok, status"},{"title":"Pobieranie raportu","desc":"Eksport raportów lub wersji roboczych do PDF na potrzeby dokumentacji lub pracy offline.","alt":"Raport sekcji zwłok NPS29-00034 z opcją pobrania — przydatność zwłok i szczegóły"},{"title":"Oś czasu","desc":"Każde działanie zapisane z użytkownikiem i znacznikiem czasu.","alt":"Oś czasu historii sekcji zwłok: sekcja zakończona przez Mayur Bendre"}]},"fetal-death":{"title":"Obumarcie płodu","intro":"Moduł Obumarcie płodu rejestruje przypadki obumarcia płodu na wybiegach i nimi zarządza, zapisując przyczynę, czas i powiązane dane zwierząt. Wspiera opiekę weterynaryjną, monitorowanie zdrowia rozrodczego, analizę trendów i lepsze zarządzanie populacją.","summary":"Rejestruje przypadki obumarcia płodu na wybiegach i nimi zarządza","features":[{"title":"Dodawanie wpisu obumarcia płodu","desc":"Rejestrowanie nowych przypadków: przyczyna, czas, rodzice, dane zwierzęcia.","alt":"Formularz dodawania obumarcia płodu z wybiegiem, gatunkiem i rodzicem"},{"title":"Wyszukiwanie i filtry","desc":"Wyszukiwanie według słowa kluczowego; filtrowanie według lokalizacji, daty, martwego urodzenia lub poronienia, gatunku albo płci.","alt":"Lista obumarć płodu z wyszukiwaniem i filtrem"},{"title":"Podgląd wpisów zgonów","desc":"Pełne dane, liczba dni od zgonu, przyczyna, ID, wybieg, lokalizacja, płeć.","alt":"Lista wpisów obumarcia płodu, karta Martwe urodzenia"},{"title":"Wyświetlanie karty zwierzęcia","desc":"FID, gatunek, odnalezienie, rodzice, lokalizacja, płeć, zgłaszający.","alt":"Karta podsumowania obumarcia płodu"},{"title":"Edycja wpisu","desc":"Modyfikacja istniejącego wpisu z poziomu podsumowania, z zapisem w historii zmian.","alt":"Podsumowanie obumarcia płodu z ikoną ołówka do edycji"},{"title":"Usuwanie wpisu","desc":"Usunięcie wpisu w razie potrzeby, z pełnym zapisem w historii zmian.","alt":"Podsumowanie obumarcia płodu z opcją „Usuń obumarcie płodu” (Delete Fetal Death)"}]},"egg-management-app":{"title":"Zarządzanie jajami — App","intro":"Moduł Jaja śledzi pełny cykl życia jaj — od zniesienia do wyklucia lub przeniesienia do odchowalni — zapewniając dokładną dokumentację, aktualizacje w czasie rzeczywistym i pełną identyfikowalność, co usprawnia koordynację i rozliczalność zespołów gniazd, odchowalni i wylęgarni.","summary":"Śledzi pełny cykl życia jaj","features":[{"title":"Panel jaj","desc":"Bieżące liczby: jaja w gniazdach, przeniesione do odchowalni, przeznaczone do utylizacji.","alt":"Panel zbioru jaj: 66 w gnieździe, 76 do odchowalni, 35 do utylizacji"},{"title":"Wprowadzanie jaj (gniazdo / odchowalnia)","desc":"Dodawanie jaj z rodzicami, stanem, datami, gatunkiem, notatkami i załącznikami.","alt":"Formularz dodawania jaj z wybiegiem, rodzicami i miejscem jaja"},{"title":"Śledzenie cyklu życia","desc":"Status, masa i pełna oś czasu drogi jaja (Egg Journey Timeline).","alt":"Oś czasu drogi jaja: wyklute, inkubacja naturalna"},{"title":"Inkubacja naturalna","desc":"Jaja wysiadywane w gniazdach: ID, data zebrania, stan.","alt":"Lista jaj w gnieździe z wpisami pawia"},{"title":"Inkubacja sztuczna","desc":"Jaja w odchowalni: ocena, przeniesienie do inkubacji, utylizacja lub wyklucie.","alt":"Lista jaj do odchowalni"},{"title":"Przeniesienia jaj","desc":"Śledzenie lokalizacji, etapu, daty wyklucia, gatunku, ID i płci.","alt":"Przeniesione jaja — zbiorcze wnioski o przeniesienie"},{"title":"Utylizacja jaj","desc":"Utylizacja jaj niezdolnych do rozwoju z zapisem przyczyny i historią zmian.","alt":"Lista jaj do utylizacji"},{"title":"Tworzenie ID zwierzęcia","desc":"Generowanie wpisu dla wyklutych jaj, powiązanego z gatunkiem i rodzicami.","alt":"Wyklute jaja — „Utwórz ID zwierzęcia” (Create Animal ID)"}]},"egg-management-web":{"title":"Zarządzanie jajami — Web","intro":"Webowe uzupełnienie modułu Zarządzanie jajami, z którego korzystają przełożeni i kierownicy odchowalni, aby konfigurować inkubatory, generować raporty i śledzić jaja na każdym etapie cyklu życia. Pełna identyfikowalność, widoki z filtrami i raporty do eksportu na potrzeby zgodności z przepisami i przeglądów.","summary":"Służy przełożonym i kierownikom odchowalni do konfiguracji inkubatorów, generowania raportów i śledzenia jaj na każdym etapie cyklu życia","features":[{"title":"Konfiguracja odchowalni i inkubatorów","desc":"Tworzenie odchowalni powiązanych z lokalizacjami, tworzenie pomieszczeń, zarządzanie inkubatorami.","alt":"Lista odchowalni z pomieszczeniami, inkubatorami i lokalizacjami"},{"title":"Raportowanie, filtry i dostęp do danych","desc":"Filtrowanie według lokalizacji, gatunku, daty lub etapu; eksport raportów.","alt":"Tabela statystyk jaj według gatunku"},{"title":"Lista jaj","desc":"Karty według statusu: Przyjęte, Inkubacja, Wyklute, Zutylizowane, Wszystkie.","alt":"Lista jaj z kartami Przyjęte, Inkubacja, Wyklute"}]},"announcement":{"title":"Ogłoszenia","intro":"Moduł Ogłoszenia to centralne narzędzie do przekazywania ważnych informacji i ogólnych komunikatów między zespołami i lokalizacjami. Umożliwia komunikację skierowaną do wybranych odbiorców, planowanie publikacji i interakcję, dzięki czemu właściwy komunikat trafia do właściwych osób we właściwym czasie.","summary":"Centralne narzędzie do przekazywania ważnych informacji i ogólnych komunikatów między zespołami i lokalizacjami","features":[{"title":"Rodzaje ogłoszeń","desc":"Ogólne i ważne, każde z własnymi zasadami widoczności.","alt":"Lista ogłoszeń z kartami Wszystkie i Utworzone przeze mnie oraz kartami ogłoszeń ważnych i zwykłych"},{"title":"Wspólna lista","desc":"Wszystkie ogłoszenia w jednym widoku, własne oddzielone od cudzych.","alt":"Szczegóły ogłoszenia: Every Move Counts z dołączonym obrazem"},{"title":"Tworzenie ogłoszeń","desc":"Określenie rodzaju, tytułu i widoczności; publikacja od razu lub zaplanowana; podgląd i załączniki.","alt":"Szczegóły ogłoszenia: Every necropsy counts, z przyciskiem tworzenia"},{"title":"Działania po publikacji","desc":"Edycja, anulowanie lub usuwanie ogłoszeń. Powiadomienia i strona główna zapewniają, że widzą je właściwe osoby.","alt":"Szczegóły ogłoszenia ogólnego z otwartym menu Edytuj, Anuluj, Usuń"}]},"helpdesk-module":{"title":"Moduł Helpdesk","intro":"Moduł Wnioski pomaga personelowi zoo składać i śledzić wnioski dotyczące zasobów, konserwacji lub usług, zapewniając rozliczalność, szybsze załatwianie spraw i lepszą koordynację między działami. Zastępuje e-maile i papierowe formularze jednym, audytowalnym rejestrem.","summary":"Pomaga personelowi zoo składać i śledzić wnioski dotyczące zasobów, konserwacji lub usług, zapewniając rozliczalność, szybsze załatwianie spraw i lepszą koordynację między działami","features":[{"title":"Przegląd wniosków według statusu","desc":"Oczekujące, Zatwierdzone, Odrzucone, Anulowane, W toku, Zakończone.","alt":"Lista Help Desk z kartami Oczekuje na zatwierdzenie, Zatwierdzone, Odrzucone, Anulowane"},{"title":"Zarządzanie wnioskami","desc":"Składanie, edycja, anulowanie lub odrzucanie wniosków z priorytetami.","alt":"Szczegóły wniosku stolarskiego z wykonawcą i kosztorysem"},{"title":"Zarządzanie kosztami","desc":"Dodawanie, edycja, powielanie lub usuwanie kosztorysów dla poszczególnych pozycji.","alt":"Zestawienie kosztów: pozycje pokrycie dachu i drewno"},{"title":"Realizacja i cofnięcie","desc":"Oznaczanie wniosków jako zrealizowanych lub przywracanie ich do statusu „W toku”.","alt":"Wniosek zakończony z opcją „Przywróć do W toku” (Move Back To In-Progress)"}]},"security":{"title":"Ochrona","intro":"Moduł Ochrona zarządza uprawnieniami dla poszczególnych lokalizacji i nadzoruje procesy przenoszenia i utylizacji jaj oraz wszelkie przeniesienia zwierząt i do szpitala, zapewniając kontrolowane przemieszczanie i pełną rozliczalność: kto, czym i kiedy się zajmował.","summary":"Zarządza uprawnieniami dla lokalizacji i nadzoruje przenoszenie i utylizację jaj oraz przeniesienia zwierząt i do szpitala, zapewniając pełną rozliczalność: kto, czym i kiedy się zajmował","features":[{"title":"Filtrowanie","desc":"Filtrowanie wpisów według statusu — Pokaż wszystkie, Oczekuje na odprawę wyjazdową, Odprawa ochrony zakończona — w celu ukierunkowanego przeglądu.","alt":"Okno filtrowania: Pokaż wszystkie, Oczekuje na odprawę wyjazdową, Odprawa ochrony zakończona"},{"title":"Odprawa wjazdowa i wyjazdowa","desc":"Upoważniony pracownik ochrony przeprowadza odprawę wjazdową i wyjazdową przy przeniesieniach jaj, zwierząt i do szpitala.","alt":"Przeniesienie INT-02997 z przyciskiem odprawy wyjazdowej przez ochronę (Security Checkout)"}]},"reports-app":{"title":"Raporty - App","intro":"Moduł Raporty przedstawia skategoryzowane dane o kluczowych zdarzeniach dotyczących zwierząt, uporządkowane pod konkretnymi nagłówkami, co umożliwia szybkie wnioski i analizę w dowolnym miejscu.","summary":"Przedstawia skategoryzowane dane o kluczowych zdarzeniach dotyczących zwierząt, uporządkowane pod konkretnymi nagłówkami, do szybkiej analizy w dowolnym miejscu","features":[{"title":"Filtry","desc":"Zawężanie raportów według daty, lokalizacji lub gatunku.","alt":"Raport kluczowych wskaźników: filtr dzień/tydzień/miesiąc, data, urodzenia i podział na gatunki"},{"title":"Statystyki","desc":"Filtrowanie według daty i statystyki według kategorii: urodzenia, zgony, nowe przybycia, przeniesienia między lokalizacjami (przychodzące/wychodzące), zewnętrzne, przeniesienia wewnętrzne i marnowanie paszy.","alt":"Wybór kategorii statystyk: urodzenia, zgony, nowe przybycia, przeniesienia między lokalizacjami, przeniesienia zewnętrzne"}]},"reports-web":{"title":"Raporty (Web)","intro":"Wersja webowa generuje czytelne raporty do pobrania dotyczące danych i działań związanych ze zwierzętami, obejmujące urodzenia, zgony, przeniesienia i oceny, oparte na tych samych wpisach co aplikacja.","summary":"Generuje czytelne raporty do pobrania dotyczące danych i działań związanych ze zwierzętami","features":[{"title":"Filtry i wyszukiwanie","desc":"Zawężanie raportów według daty, lokalizacji lub gatunku.","alt":"Ogólny raport gatunków: pobieranie raportu, wybór lokalizacji, pokazywanie/ukrywanie filtrów oraz tabela gatunków z liczbą samców, samic, osobników o nieustalonej i nieokreślonej płci"},{"title":"Raporty do pobrania","desc":"Generowanie, przeglądanie i pobieranie raportów: gatunki, dzienny, lista zwierząt, ocena zwierząt, opiekunowie zwierząt, użytkownicy, obserwacje, dziennik opiekuna, dziennik biologa i liczebność na wybiegach — na potrzeby zgodności z przepisami i dostępu offline.","alt":"Ogólny raport gatunków: pobieranie raportu, wybór lokalizacji, pokazywanie/ukrywanie filtrów oraz tabela gatunków z liczbą samców, samic, osobników o nieustalonej i nieokreślonej płci"}]},"lab":{"title":"Laboratorium","intro":"Moduł Laboratorium gromadzi w jednym miejscu zlecenia i wyniki badań diagnostycznych, usprawnia współpracę lekarzy weterynarii z laboratoriami, wspiera wczesne wykrywanie i leczenie chorób oraz prowadzi bezpieczne cyfrowe repozytorium na potrzeby bioasekuracji, audytów i analiz.","summary":"Gromadzi zlecenia i wyniki badań diagnostycznych, usprawnia współpracę lekarzy weterynarii z laboratoriami, wspiera wczesne wykrywanie i leczenie chorób oraz prowadzi bezpieczne cyfrowe repozytorium na potrzeby bioasekuracji, audytów i analiz","features":[{"title":"Lista zleceń i filtrowanie","desc":"Podgląd i filtrowanie zleceń laboratoryjnych według laboratorium, wyszukiwania lub statusu — Oczekujące, W toku, Zakończone — z ikonami oznaczonymi kolorami.","alt":"Naukowiec pracujący przy mikroskopie."},{"title":"Szczegółowy widok zlecenia","desc":"Podgląd zlecającego, zwierzęcia, lokalizacji i powiązanego wpisu medycznego; aktualizacja statusu w czasie rzeczywistym z automatyczną synchronizacją między modułami.","alt":""},{"title":"Lokalizacja i kontrola dostępu","desc":"Oznaczanie laboratoriów według lokalizacji; decydowanie, kto może konfigurować lub przeglądać dane laboratoryjne.","alt":""},{"title":"Przypisanie badań do lokalizacji","desc":"Przypisywanie laboratoriów do konkretnych badań diagnostycznych bezpośrednio na karcie „Konfiguracja” (Config) lokalizacji.","alt":""},{"title":"Przypisanie pojedyncze i zbiorcze","desc":"Przypisanie laboratorium do każdego badania osobno lub wszystkich badań do domyślnego laboratorium jednym kliknięciem.","alt":""},{"title":"Zarządzanie badaniami i próbkami","desc":"Tworzenie badań laboratoryjnych, badań cząstkowych i rodzajów próbek (surowica, płyn mózgowo-rdzeniowy itp.) oraz przypisywanie ich do właściwych laboratoriów.","alt":""},{"title":"Aktualizacja statusu badania","desc":"Śledzenie etapów: Oczekuje na próbkę → Próbka przyjęta / odrzucona / skrzepnięta / zhemolizowana / niewystarczająca → W toku → Zakończone (dodatni / ujemny / wykryto / nie wykryto / niejednoznaczny).","alt":""},{"title":"Zmiana laboratorium","desc":"Przeniesienie badań do innego laboratorium w razie potrzeby, bez zakłócania pracy.","alt":""}]},"diet":{"title":"Dieta","intro":"Moduł Dieta to centralna platforma do sprawnego planowania diet zwierząt i zarządzania nimi. Umożliwia zespołom żywieniowym tworzenie uporządkowanych planów diety z konfigurowalnych składników, produktów, rodzajów paszy, receptur i zestawów oraz planowanie posiłków według godziny, dnia lub etapu życia.","summary":"Centralna platforma do sprawnego planowania diet zwierząt i zarządzania nimi","features":[{"title":"Konfiguracja diety","desc":"Tworzenie diet z rodzajów paszy, produktów, receptur i mieszanek; planowanie posiłków według godziny, dnia lub etapu życia; przypisywanie według gatunku lub osobnika; aktywowanie, klonowanie i przypisywanie diet; dołączanie materiałów źródłowych.","alt":"Świeże owoce przygotowane jako pokarm dla zwierząt."},{"title":"Sposoby przygotowania i wielkość kawałków","desc":"Tworzenie sposobów przygotowania produktów, receptur i zestawów oraz zarządzanie nimi, aby zapewnić stałą wartość odżywczą i konsystencję.","alt":""},{"title":"Rodzaje paszy","desc":"Centralna lista kategorii paszy z wyszukiwaniem, zapewniająca spójne planowanie diet.","alt":""},{"title":"Produkty","desc":"Dodawanie, edycja i usuwanie składników diety ze szczegółowymi opisami i zdjęciami.","alt":""},{"title":"Receptury i mieszanki","desc":"Receptury i mieszanki wieloskładnikowe — receptury według określonych ilości, mieszanki według udziału procentowego produktów — z komponentami wielokrotnego użytku i pełnym dziennikiem działań.","alt":""},{"title":"Grupy żywieniowe","desc":"Grupowanie wybiegów w celu skoordynowania harmonogramów karmienia i przypisań diet, z filtrami według lokalizacji, sekcji i gatunku.","alt":""}]},"pharmacy-app":{"title":"Apteka (App)","intro":"Umożliwia szybkie, dokładne i identyfikowalne wydawanie produktów leczniczych bezpośrednio upoważnionym lekarzom, zapewniając terminową realizację i automatyczną aktualizację stanów magazynowych.","summary":"Umożliwia szybkie, dokładne i identyfikowalne wydawanie produktów leczniczych bezpośrednio upoważnionym lekarzom","features":[{"title":"Zamawianie w aplikacji","desc":"Użytkownicy mogą zamawiać produkty z apteki bezpośrednio w aplikacji.","alt":"Lista wydań: 11 wydań z ID zamówień, apteką, datą, zamawiającym, lekiem i łączną ilością oraz przycisk „Nowe wydanie” (New Dispense)"},{"title":"Wydawanie w aplikacji","desc":"Magazyny mogą wydawać produkty z apteki bezpośrednio w aplikacji.","alt":"Szczegóły wydania DIS279: Local Pharmacy, wydano dla Antz Admin, jeden lek Crocin o łącznej ilości 100"}]},"pharmacy-web":{"title":"Apteka (Web)","intro":"Umożliwia szybkie, dokładne i identyfikowalne wydawanie produktów leczniczych bezpośrednio upoważnionym lekarzom, zapewniając terminową realizację i automatyczną aktualizację stanów magazynowych — od recepty aż po półkę — z wglądem na poziomie serii i śledzeniem terminów ważności na każdym etapie.","summary":"Umożliwia szybkie, dokładne i identyfikowalne wydawanie produktów leczniczych bezpośrednio upoważnionym lekarzom","features":[{"title":"Panel","desc":"Bieżące informacje o problemach z zapasami, dostawach, zakupach, zamówieniach, zużyciu, terminach ważności i szybko rotujących produktach, z wizualizacją trendów ułatwiającą szybkie działanie.","alt":"Farmaceuta porządkujący półki z lekami."},{"title":"Inteligentne wyszukiwanie i filtry","desc":"Szybkie wyszukiwanie wpisów według ID zamówienia, nazwiska lekarza lub apteki.","alt":""},{"title":"Dane podstawowe (regały i półki)","desc":"Organizacja magazynu według liczby regałów i półek dla szybkiego dostępu i aktualizacji, z konfigurowalnymi danymi (opakowania, jednostki miary, substancje czynne, kierowcy, producenci).","alt":""},{"title":"Zarządzanie raportami stanów","desc":"Stany według serii z wartością i terminem ważności; oznaczanie pozycji o niskim stanie lub przeterminowanych; monitorowanie zbliżających się terminów ważności; zarządzanie depozytem z rozstrzyganiem sporów.","alt":""},{"title":"Zarządzanie produktami i magazynem","desc":"Tworzenie produktów, śledzenie stanów i terminów ważności, rejestrowanie zakupów i wysyłek, prowadzenie jednolitej księgi, obsługa zamienników i wariantów.","alt":""},{"title":"Zarządzanie wydawaniem","desc":"Lekarze mogą przepisywać i wydawać leki lub odbierać je bezpośrednio z apteki — wszystko jest rejestrowane.","alt":""},{"title":"Zarządzanie dostawami","desc":"Śledzenie przychodzących i wychodzących dostaw leków oraz ich realizacja w aplikacji.","alt":""},{"title":"Korekty stanów i raporty","desc":"Rejestrowanie zmian stanów (braki, uszkodzenia, przeterminowanie); prowadzenie historii zmian; obsługa zwrotów do dostawców; pobieranie raportów zużycia, zwrotów, zakupów i wydań na potrzeby finansów i planowania zapotrzebowania.","alt":""}]},"compliance":{"title":"Zgodność z przepisami","intro":"Moduł Zgodność z przepisami zapewnia w aplikacji widok na poziomie organizacji zarządzania zwierzętami w wielu schroniskach, fundacjach i trustach oraz daje dostęp do dokumentacji eksportu, importu, wysyłek i gatunków, przechowując wszystkie dokumenty regulacyjne w jednym zaufanym miejscu z możliwością pobrania.","summary":"Widok na poziomie organizacji zarządzania zwierzętami w wielu schroniskach, fundacjach i trustach oraz dostęp do dokumentacji eksportu, importu, wysyłek i gatunków","features":[{"title":"Przegląd organizacji","desc":"Wszystkie organizacje zarejestrowane w systemie w jednym widoku.","alt":"Ośrodek ochrony przyrody z wieloma obiektami."},{"title":"Liczba gatunków i zwierząt","desc":"Liczba gatunków i łączna liczba zwierząt należących do każdej organizacji.","alt":""},{"title":"Zasięg lokalizacji","desc":"Liczba lokalizacji zarządzających zwierzętami w ramach każdej organizacji.","alt":""},{"title":"Przejrzystość i rozliczalność","desc":"Dokładne raportowanie i wgląd w populacje zwierząt we wszystkich organizacjach.","alt":""},{"title":"Filtry i pobieranie","desc":"Filtrowanie i pobieranie dokumentów dla wybranego zakresu dat.","alt":""},{"title":"Eksport i import","desc":"Rejestrowanie i edycja formularzy zezwoleń dla zwierząt eksportowanych do innego kraju lub ośrodka albo importowanych stamtąd.","alt":""},{"title":"Wysyłka","desc":"Śledzenie szczegółów wysyłki, środka transportu, daty wysyłki, kontenerów i logistyki.","alt":""},{"title":"Gatunki","desc":"Podgląd i pobieranie informacji o gatunkach objętych transakcją (ptaki, ssaki, gady).","alt":""},{"title":"Konfiguracja danych podstawowych","desc":"Konfiguracja rodzajów dokumentów i prowadzenie list importerów i eksporterów na potrzeby dokumentacji eksportu i importu.","alt":""}]}}};
